function buildSystemPrompt(unit, lang, grade) {
  // דקדוק ערבי, ועברית כשפה שנייה לדוברי ערבית - שני המקצועות האלה
  // מיועדים לדוברי ערבית, אז ההוראה תמיד בערבית, בלי קשר לטוגל השפה
  // בממשק (שקובע רק את שפת התפריטים/כפתורים).
  const effectiveLang = (unit.subject === 'ערבית' || unit.subject === 'עברית כשפה שנייה' || unit.subject === 'الرياضيات') ? 'ar' : lang;
  const langName = effectiveLang === 'ar' ? 'ערבית (Arabic)' : 'עברית (Hebrew)';
  const persona = PERSONAS[unit.subject] || PERSONAS['מתמטיקה'];
  const isMath = unit.subject === 'מתמטיקה' || unit.subject === 'الرياضيات';
  const diagramInstruction = isMath
    ? `- חובה לצייר דיאגרמה בכל פעם שמסבירים או נותנים דוגמה על נושא גיאומטרי (משולש, זווית, מרובע, מעגל, מערכת צירים, גרף פונקציה) - זה לא אופציונלי, זה חלק חובה מההסבר. גם אם התלמיד רק ביקש "דוגמה" בלי לפרט, ציור תמיד עדיף על תיאור מילולי בלבד בנושא גיאומטרי. כתוב קוד SVG פשוט ותקין, עטוף בדיוק כך:
[DIAGRAM_START]
<svg viewBox="0 0 300 220" xmlns="http://www.w3.org/2000/svg">...</svg>
[DIAGRAM_END]
כללים לציור: viewBox="0 0 300 220" תמיד. שימוש ב-stroke="#2F6F5E" לקווי הצורה, stroke-width="2", fill="none" לצורות (אלא אם צריך למלא צבע ספציפי). טקסט/תוויות בתוך ה-SVG עם <text> ו-font-size="14". צורה אחת ברורה ופשוטה בכל דיאגרמה, לא מורכבת מדי. את הדיאגרמה תמיד ממקמים אחרי ההסבר המילולי הרלוונטי אליה, לא בהתחלה.`
    : `- אם עץ תחביר, טבלת נטייה, או דיאגרמה פשוטה יעזרו להבין מבנה משפט/צורת מילה - אפשר לצייר זאת. כתוב קוד SVG פשוט ותקין, עטוף בדיוק כך:
[DIAGRAM_START]
<svg viewBox="0 0 300 220" xmlns="http://www.w3.org/2000/svg">...</svg>
[DIAGRAM_END]
כללים לציור: viewBox="0 0 300 220" תמיד. שימוש ב-stroke="#2F6F5E", stroke-width="2". טקסט עם <text> ו-font-size="14". פשוט וברור, לא מורכב מדי.`;

  return `אתה ${persona.name}, ${persona.role}, שמלמד תלמיד/ה אחד-על-אחד בשיחת וואטסאפ/צ'אט.

חומר הלימוד הרשמי שסופק לך (מקור: תוכניות הלימודים של משרד החינוך) - זהו המקור היחיד למידע שלך, אל תסטה על ידע כללי שסותר לו:
"""
${JSON.stringify(unit, null, 1)}
"""

כיתה: ${grade}'

הנחיות התנהגות:
- ענה תמיד ב${langName}, גם אם חלק מהחומר המקורי כתוב בשפה אחרת. זה חל על כל ההסבר וההנחיה שלך לאורך כל השיחה, לא רק על ההודעה הראשונה - אל תחליק לשפה אחרת באמצע ההסבר.
- זו שיטת הוראה סוקרטית, לא שאלה-ותשובות: נסה להבין איפה התלמיד/ה תקוע/ה, שאל שאלה מנחה קצרה אחת, ורק אם עדיין תקוע/ה - תן את הצעד הבא.
- אל תשתמש בכוכביות (**) או בכל סימון markdown אחר להדגשת טקסט - הצ'אט מציג טקסט רגיל בלבד, וכוכביות יופיעו כפשוטן ויבלבלו את התלמיד. אם רוצים להדגיש מילה, פשוט תכתוב אותה בלי סימנים מיוחדים, או תשתמש ברווח/שורה חדשה להפרדה.
- זהירות קריטית עם ערבוב כתבים: מותר ואף רצוי לשלב מילים שלמות משתי השפות באותו משפט (למשל מילה עברית בתוך משפט ערבי כשמלמדים אותה), אבל **אסור בהחלט** לערבב אותיות עבריות וערביות בתוך אותה מילה בודדת. אותיות מסוימות נראות דומות מאוד (ל/ل, ת/ت, ו/و, ר/ر, ה/ه) - שים לב במיוחד לא "להחליק" בטעות אות מכתב אחד לתוך מילה מהכתב השני, כי זה שובר את המילה ויוצר טקסט לא קריא. לפני שליחת התשובה, בדוק שכל מילה בודדת בנויה כולה מאותו כתב (כולה עברית או כולה ערבית), לא תערובת.
- אל תתן פתרון מלא מיד, גם אם מתבקשים. פרק לצעדים קטנים.
- כשמסבירים פתרון מדורג עם כמה נקודות/שלבים ממוספרים (1. 2. 3.), חובה להשאיר שורה ריקה בין כל נקודה לנקודה הבאה - כלומר שתי ירידות שורה (\n\n) בין השלבים, לא רק אחת. זה קריטי לקריאות בצ'אט.
- טון: חם, מעודד, סבלני. אף פעם לא מתנשא או ביקורתי על טעויות.
- הודעות קצרות, מתאים לצ'אט וואטסאפ.
- אם התלמיד עונה נכון - לחזק בקצרה ולעבור הלאה.
${diagramInstruction}

בסוף כל תגובה שלך, הוסף שורה נסתרת (התלמיד לא רואה אותה, השרת מסיר אותה):
[TOPIC: <שם הנושא הנוכחי בקצרה>]`;
}

// ---------------------------------------------------------------
// GET /api/topics?grade=ז
// מחזיר את רשימת הנושאים הזמינים לכיתה נתונה (לתפריט הבחירה בצ'אט)
// ---------------------------------------------------------------
const DOMAIN_AR = {
  'אלגברה': 'الجبر',
  'גאומטריה': 'الهندسة',
  'סטטיסטיקה': 'الإحصاء',
  'מספרים': 'الأعداد',
  'פונקציות': 'الدوال',
  'תחביר': 'النحو',
  'צורות': 'الصرف',
  'כתיב': 'الإملاء',
};

// ---------------------------------------------------------------
// GET /api/subjects?lang=he
// מחזיר את רשימת המקצועות הזמינים (כולל אלה שעדיין "בקרוב")
// ---------------------------------------------------------------
router.get('/subjects', (req, res) => {
  const lang = req.query.lang === 'ar' ? 'ar' : 'he';
  const subjects = SUBJECTS
    .filter(s => s.id === 'math'
      || (s.id === 'hebrew-grammar' && lang === 'he')
      || (s.id === 'arabic-grammar' && lang === 'ar')
      || (s.id === 'hebrew-second-language' && lang === 'ar')
      || (s.id === 'math-arabic' && lang === 'ar'))
    .map(s => ({
      id: s.id,
      name: subjectLabel(s, lang),
      available: s.available,
    }));
  res.json({ subjects });
});

router.get('/topics', (req, res) => {
  const grade = req.query.grade;
  const subjectId = req.query.subject || 'math';
  const lang = req.query.lang === 'ar' ? 'ar' : 'he';
  const subject = SUBJECTS.find(s => s.id === subjectId);

  if (!subject || !subject.available) {
    return res.json({ grades: [], topics: [] });
  }

  // גרדים זמינים בפועל עבור המקצוע הזה (לא כל GRADES באופן גורף)
  const gradesForSubject = [...new Set(
    TOPICS
      .filter(t => { const u = KB.math_units[t.id]; return u && u.subject === subject.kb_subject; })
      .map(t => t.grade)
  )].sort((a, b) => GRADES.indexOf(a) - GRADES.indexOf(b));

  if (!grade || !gradesForSubject.includes(grade)) {
    return res.json({ grades: gradesForSubject, topics: [] });
  }

  const topics = TOPICS.filter(t => t.grade === grade).map(t => {
    const unit = KB.math_units[t.id];
    return {
      id: unit ? unit.topic_id : null,
      name: lang === 'ar' ? t.ar : t.he,
      domain: lang === 'ar' ? (DOMAIN_AR[t.domain_he] || t.domain_he) : t.domain_he,
      subject: unit ? unit.subject : null,
    };
  }).filter(t => t.id && (!subject.kb_subject || t.subject === subject.kb_subject));
  res.json({ grades: GRADES, topics });
});

// ---------------------------------------------------------------
// POST /api/chat
// מקבל: message, studentId, studentName, grade, topicId, history (JSON string), image (אופציונלי)
// מחזיר: { reply, topic }
// ---------------------------------------------------------------
router.post('/chat', upload.single('image'), async (req, res) => {
  try {
    const { message, studentId, studentName, grade, topicId, subject, lang: langParam } = req.body;
    let history = [];
    try { history = JSON.parse(req.body.history || '[]'); } catch (e) { history = []; }

    const unit = findUnitById(topicId) || {};
    const lang = langParam === 'ar' ? 'ar' : (langParam === 'he' ? 'he' : (/[\u0600-\u06FF]/.test(message || '') ? 'ar' : 'he'));

    const messages = history.map(m => ({
      role: m.role === 'user' ? 'user' : 'assistant',
      content: m.text,
    }));

    const userContent = [];
    if (req.file) {
      userContent.push({
        type: 'image',
        source: {
          type: 'base64',
          media_type: req.file.mimetype,
          data: req.file.buffer.toString('base64'),
        },
      });
    }
    userContent.push({ type: 'text', text: message || 'תראה לי בבקשה מה כתוב בתמונה ועזור לי איתה' });
    messages.push({ role: 'user', content: userContent });

    const response = await anthropic.messages.create({
      model: 'claude-sonnet-4-6',
      max_tokens: 1000,
      // Prompt caching: ה-system prompt זהה לחלוטין לכל תלמיד שלומד את אותו
      // נושא/כיתה/שפה - סימון cache_control חוסך עד 90% מעלות טוקני הקלט
      // על אותו חלק בבקשות חוזרות בתוך חלון הזמן (ברירת מחדל: 5 דקות).
      system: [
        {
          type: 'text',
          text: buildSystemPrompt(unit, lang, grade || 'ז'),
          cache_control: { type: 'ephemeral' },
        },
      ],
      messages: messages,
    });

    // לוג לניטור אפקטיביות ה-caching: cache_read = טוקנים שנחסכו (10% מהמחיר),
    // cache_creation = הפעם הראשונה ששומרים (מחיר מלא + קצת), input = טוקנים רגילים
    if (response.usage) {
      console.log(
        `[cache] topic=${topicId} read=${response.usage.cache_read_input_tokens || 0} ` +
        `created=${response.usage.cache_creation_input_tokens || 0} ` +
        `regular_input=${response.usage.input_tokens || 0} output=${response.usage.output_tokens || 0}`
      );
    }

    const rawReply = response.content
      .filter(block => block.type === 'text')
      .map(block => block.text)
      .join('\n');

    const topicMatch = rawReply.match(/\[TOPIC:\s*(.+?)\]/);
    const topic = topicMatch ? topicMatch[1].trim() : (unit.topic_name || unit.topic_name_official || null);

    // חילוץ דיאגרמות SVG שהמודל צייר, והסרתן מהטקסט הרגיל
    const diagrams = [];
    let replyNoTopic = rawReply.replace(/\[TOPIC:\s*.+?\]/, '');
    const diagramRegex = /\[DIAGRAM_START\]([\s\S]*?)\[DIAGRAM_END\]/g;
    let match;
    while ((match = diagramRegex.exec(replyNoTopic)) !== null) {
      const svg = match[1].trim();
      if (svg.startsWith('<svg')) diagrams.push(svg);
    }
    let cleanReply = replyNoTopic.replace(diagramRegex, '').trim();
    // רשת ביטחון: מסירים כוכביות markdown, למקרה שהמודל בכל זאת השתמש בהן
    cleanReply = cleanReply.replace(/\*\*(.+?)\*\*/g, '$1').replace(/\*(.+?)\*/g, '$1');

    // TODO: שמירה למסד נתונים לצורך דוח שבועי להורים:
    // studentId, studentName, grade, topic, timestamp

    res.json({ reply: cleanReply, topic, diagrams });
  } catch (err) {
    console.error('Chat error:', err);
    res.status(500).json({ error: 'internal_error' });
  }
});

module.exports = router;
